## ---- setup ----
source("_common.R")
library(tidypm)
library(knitr)
# Error messages are part of what this chapter shows, so they are printed in
# the language of the book rather than in the language of the machine.
Sys.setenv(LANGUAGE = "en")

## ---- packages ----
lock <- jsonlite::read_json("renv.lock")
n_pinned <- length(lock$Packages)
v <- function(p) lock$Packages[[p]]$Version %||% "--"

packages <- tibble::tribble(
  ~group,        ~package,               ~role,
  "data models", "tidyverse",            "dplyr to build, filter and join; tidyr to pivot; ggplot2 for every figure",
  "data models", "xts, zoo",             "the date-indexed matrix every optimizer consumes",
  "the subject", "PortfolioAnalytics",   "portfolio specification and optimization",
  "the subject", "PerformanceAnalytics", "moments, drawdowns, performance tables, exploratory charts",
  "solvers",     "ROI, ROI.plugin.quadprog, ROI.plugin.glpk, quadprog", "quadratic and linear programs behind `optimize_method = \"ROI\"`",
  "solvers",     "osqp, CVXR",           "convex problems behind `optimize_method = \"CVXR\"`",
  "solvers",     "DEoptim, GenSA, pso",  "metaheuristics for problems that are not convex",
  "estimation",  "corpcor",              "shrinkage covariance",
  "companion",   "tidypm",               "the modeled market and the tibble--xts boundary",
  "tooling",     "renv",                 "pins every version in `renv.lock`"
)

## ---- tbl-01-packages ----
# The packages this book uses, grouped by what they do. Versions are read from
# the lockfile.
packages |>
  dplyr::mutate(version = vapply(sub(",.*$", "", package), v, character(1))) |>
  dplyr::select(group, package, version, role) |>
  kable(align = "llll", col.names = c("", "package", "version", "used for"))

## ---- namespace ----
exports <- getNamespaceExports("PortfolioAnalytics")
legacy  <- sort(grep("_v[12]", exports, value = TRUE))
c(exports = length(exports), legacy = length(legacy))
legacy

## ---- namespace-data ----
n_fetch <- sum(grepl("download|getSymbols|fetch|read", exports, ignore.case = TRUE))
pa_data <- utils::data(package = "PortfolioAnalytics")$results[, "Item"]

